/**
 * Manual TypeScript Type Definitions
 *
 * These types cannot be auto-generated by typeshare because they use
 * features that typeshare doesn't support (e.g., #[serde(flatten)],
 * internally tagged enums without content attribute).
 *
 * Keep these in sync with the corresponding Rust types in:
 * crates/openflow-contracts/src/entities/
 * crates/openflow-contracts/src/events/
 */

import type {
  AgentMessageRole,
  AgentStats,
  Chat,
  CompletionStatus,
  Message,
  ToolResultStatus,
} from './types';

/**
 * Chat with all its messages
 *
 * Corresponds to: crates/openflow-contracts/src/entities/chat.rs::ChatWithMessages
 *
 * The Rust type uses #[serde(flatten)] on the chat field, which means
 * all Chat properties are flattened into this interface directly.
 *
 * TODO: Update frontend code that uses `chatWithMessages.chat.title`
 * to use `chatWithMessages.title` directly after the Rust change.
 */
export interface ChatWithMessages extends Chat {
  /** All messages in this chat, ordered by created_at ASC */
  messages: Message[];
}

/**
 * Settings map (key-value store)
 *
 * Corresponds to: crates/openflow-contracts/src/entities/settings.rs::SettingsMap
 */
export type SettingsMap = Record<string, string>;

// =============================================================================
// Agent Event Types (internally tagged enums)
//
// These use #[serde(tag = "type", rename_all = "snake_case")] in Rust which
// produces internally-tagged JSON like: {"type": "text", "text": "..."}
// typeshare doesn't support this format, so we define them manually.
// =============================================================================

/**
 * A block of content in a message
 *
 * Corresponds to: crates/openflow-contracts/src/events/agent_event.rs::ContentBlock
 *
 * Messages can contain multiple content blocks of different types.
 * This allows rich content like text mixed with tool results.
 */
export type ContentBlock =
  | ContentBlockText
  | ContentBlockToolUse
  | ContentBlockToolResult
  | ContentBlockThinking;

export interface ContentBlockText {
  type: 'text';
  /** The text content */
  text: string;
}

export interface ContentBlockToolUse {
  type: 'tool_use';
  /** Unique ID for this tool use (for matching with results) */
  id: string;
  /** Name of the tool being called */
  name: string;
  /** Input arguments as JSON */
  input: unknown;
}

export interface ContentBlockToolResult {
  type: 'tool_result';
  /** ID of the tool use this is a result for */
  tool_use_id: string;
  /** The output from the tool */
  content: string;
  /** Whether this result represents an error */
  is_error?: boolean;
}

export interface ContentBlockThinking {
  type: 'thinking';
  /** The reasoning text */
  thinking: string;
}

/**
 * Unified event type for all agent providers
 *
 * Corresponds to: crates/openflow-contracts/src/events/agent_event.rs::UnifiedAgentEvent
 *
 * This type normalizes the different output formats from Claude Code, Gemini CLI,
 * Codex CLI, and other tools into a common format.
 */
export type UnifiedAgentEvent =
  | UnifiedAgentEventInit
  | UnifiedAgentEventMessage
  | UnifiedAgentEventToolUse
  | UnifiedAgentEventToolResult
  | UnifiedAgentEventComplete
  | UnifiedAgentEventError
  | UnifiedAgentEventPermission;

/** Session initialization event */
export interface UnifiedAgentEventInit {
  type: 'init';
  /** Session ID (may be external session ID for resume) */
  session_id: string;
  /** Model being used (e.g., "claude-sonnet-4-20250514") */
  model: string;
  /** List of available tool names */
  tools: string[];
}

/** A message in the conversation */
export interface UnifiedAgentEventMessage {
  type: 'message';
  /** Role of the message author */
  role: AgentMessageRole;
  /** Content blocks (text, tool use, tool result, etc.) */
  content: ContentBlock[];
}

/** Agent is calling a tool */
export interface UnifiedAgentEventToolUse {
  type: 'tool_use';
  /** Unique ID for this tool call */
  tool_id: string;
  /** Name of the tool being called */
  tool_name: string;
  /** Input arguments as JSON */
  input: unknown;
}

/** Result from a tool execution */
export interface UnifiedAgentEventToolResult {
  type: 'tool_result';
  /** ID of the tool use this is a result for */
  tool_id: string;
  /** Status of the tool execution */
  status: ToolResultStatus;
  /** Output from the tool */
  output: string;
}

/** Session completed */
export interface UnifiedAgentEventComplete {
  type: 'complete';
  /** How the session completed */
  status: CompletionStatus;
  /** Optional session statistics */
  stats?: AgentStats;
}

/** An error occurred */
export interface UnifiedAgentEventError {
  type: 'error';
  /** Error code (e.g., "rate_limit", "context_exceeded") */
  code: string;
  /** Human-readable error message */
  message: string;
}

/** Permission request from agent */
export interface UnifiedAgentEventPermission {
  type: 'permission';
  /** Name of the tool requesting permission */
  tool_name: string;
  /** Human-readable description of the action */
  description: string;
  /** Optional file path if the operation involves a specific file */
  file_path?: string;
}

// =============================================================================
// Agent Session Request Types
// =============================================================================

/**
 * Request to write input to an agent session
 */
export interface WriteAgentInputRequest {
  /** The input string to send to the agent's stdin */
  input: string;
}

/**
 * Request to resize an agent session terminal
 */
export interface ResizeAgentSessionRequest {
  /** Number of terminal columns */
  cols: number;
  /** Number of terminal rows */
  rows: number;
}

/**
 * Request to respond to a permission prompt
 */
export interface RespondPermissionRequest {
  /** The permission ID to respond to */
  permissionId: string;
  /** Whether to approve (true) or deny (false) the permission */
  approved: boolean;
}

/**
 * Session summary for list views
 */
export interface SessionSummary {
  /** Session ID */
  id: string;
  /** Process ID */
  processId: string;
  /** Provider ID (e.g., "claude-code") */
  providerId: string;
  /** Session status */
  status: string;
  /** When the session started (ISO 8601) */
  startedAt: string;
  /** When the session ended (ISO 8601), null if still running */
  endedAt?: string;
  /** Number of events in this session */
  eventCount: number;
  /** Number of tool invocations */
  toolCount: number;
  /** Whether there's a pending permission request */
  hasPendingPermission: boolean;
}
